<script module lang="ts">
/**
 * An application's command menus in one row (`design/components/menubar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menubar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, setContext } from 'svelte'

import * as zag from '@zag-js/menu'
import { useMachine } from '@zag-js/svelte'

import {
  Icon,
  Portal,
  afterRender,
  agentMember,
  attributes,
  chooseMenubarEntry,
  followHighlight,
  joinSlot,
  menubarChoices,
  menubarEdge,
  menubarEntries,
  menubarNeighbour,
  menubarStop,
  mergeParts,
  normalizeProps,
  roveMenubar,
  useDirection,
  useMediaQuery,
  watchEffect,
} from '@polymorph/svelte'
import { usePresence } from '@polymorph/svelte/motion'
import styles from '@polymorph/recipes/overlays/menubar.module.css'
import Button from '../controls/Button.svelte'
import Kbd from '../structure/Kbd.svelte'
import Menu from './Menu.svelte'
import MenubarSubmenu from './MenubarSubmenu.svelte'
import type { MenuEntry } from './Menu.svelte'

export interface MenubarMenu {
  label: string
  entries: MenuEntry[]
  disabled?: boolean
}

export interface MenubarProps {
  /**
   * The title whose menu is open on mount, for galleries and tests; screens let the user open
   * it.
   */
  defaultOpen?: string
  /**
   * Names the bar, and the one Button the bar becomes at a phone's width.
   */
  label: string
  menus: MenubarMenu[]
}
</script>

<script lang="ts">
let { defaultOpen, label: labelOwn, menus }: MenubarProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
// svelte-ignore state_referenced_locally
let last = $state((defaultOpen ?? null) as string | null)
let bar = $state<HTMLElement | null>(null)
let panel = $state<HTMLElement | null>(null)
const phone = useMediaQuery('phone')
const stop = $derived(menubarStop(menus, last))
const collapsed = $derived(menubarEntries(menus))
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  () =>
    ({
      id: uid,
      dir: documentDirection.current,
      defaultOpen: defaultOpen !== undefined,
      defaultTriggerValue: defaultOpen,
      positioning: { placement: 'bottom-start', gutter: 2 },
      onSelect: (details) => {
        entries.forEach(
          (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
        )
      },
    }) as Partial<zag.Props>,
)
const api = $derived(zag.connect(service, normalizeProps))
const entries = $derived(menus.find((menu) => menu.label === api.triggerValue)?.entries ?? [])
const handOff = $derived((event: KeyboardEvent, child?: { setOpen(open: boolean): void }): void => {
  const to = menubarNeighbour(event, bar, panel)
  const next = to === undefined ? undefined : menus[to]
  if (next === undefined) return
  event.preventDefault()
  event.stopPropagation()
  child?.setOpen(false)
  api.setTriggerValue(next.label)
  afterRender(() => {
    const first = menubarEdge(panel, 'first')?.getAttribute('data-value')
    if (first) api.setHighlightedValue(first)
  })
})
const hover = $derived((event: Event, menu: MenubarMenu): void => {
  if (!(event instanceof PointerEvent) || event.pointerType !== 'mouse') return
  if (menu.disabled === true) return
  if (!api.open || api.triggerValue === menu.label) return
  api.setTriggerValue(menu.label)
  // The machine reads an empty value as no row, so the last menu's row is not carried over.
  api.setHighlightedValue('')
})
const present = usePresence(
  () => api.open && !phone.current,
  () => panel,
)
setContext('polymorph:Menubar', {
  get api() {
    return api
  },
  get service() {
    return service
  },
  get handOff() {
    return handOff
  },
})
const effect1 = () => {
  followHighlight(panel, api.highlightedValue)
}
watchEffect(effect1, { watch: () => api.highlightedValue })
const effect2 = () => {
  api.triggerValue && (last = api.triggerValue)
}
watchEffect(effect2, { watch: () => api.triggerValue, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Menubar',
    element: () => bar,
    state: () => ({ open: api.open, entries: menubarChoices(menus) }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) => chooseMenubarEntry(menus, value) && api.open && api.setOpen(false),
      },
      close: () => api.open && api.setOpen(false),
    },
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if phone.current
    }<div class={styles.collapsed} data-member="menubar"
      >{#snippet triggerOfMenu1()
        }<Button variant="ghost" tone="neutral" iconOnly={true} icon="overflow" {label}
      />{/snippet
      }<Menu items={collapsed} trigger={triggerOfMenu1}
    /></div
  >{:else
    }<div bind:this={bar} class={styles.bar} role="menubar" aria-label={label} data-member="menubar"
      >{#each menus as menu (menu.label)
        }<button
          {...attributes(mergeParts(api.getTriggerProps({ value: menu.label }), { onKeydown: (event: KeyboardEvent) => { roveMenubar(event) }, onPointerenter: (event: Event) => { hover(event, menu) }, onFocus: () => { last = menu.label } }))}
          class={styles.title}
          role="menuitem"
          data-menubar-part="title"
          data-state={api.open && api.triggerValue === menu.label ? 'open' : 'closed'}
          aria-expanded={api.open && api.triggerValue === menu.label}
          aria-controls={api.open && api.triggerValue === menu.label ? api.getContentProps().id : undefined}
          disabled={menu.disabled === true}
          data-disabled={(menu.disabled === true) ? '' : undefined}
          tabindex={(menu.label === stop ? 0 : -1) as never}
          >{menu.label
        }</button
      >{/each
    }</div
    ><Portal
      >{#if present.current
        }<div {...attributes(api.getPositionerProps())}
          ><div
            bind:this={panel}
            {...attributes(mergeParts(api.getContentProps(), { onFocus: () => { followHighlight(panel, api.highlightedValue) }, onKeydownCapture: (event: KeyboardEvent) => { handOff(event) } }))}
            class={styles.content}
            style:--radix-dropdown-menu-content-available-height={'var(--available-height)'}
            style:--radix-dropdown-menu-content-transform-origin={'var(--transform-origin)'}
            hidden={undefined}
            data-menubar-part="panel"
            data-member="menubar"
            >{#each entries as entry, index (index)
              }{#if entry.kind === 'separator'
                }<div {...attributes(api.getSeparatorProps())} class={styles.separator}></div
              >{:else if entry.kind === 'label'
                }<div class={styles.groupLabel}>{entry.label}</div
              >{:else if entry.kind === 'checkbox'
                }<div
                  {...attributes(mergeParts(api.getOptionItemProps({ type: 'checkbox', value: entry.label, checked: entry.checked, disabled: entry.disabled, closeOnSelect: false, onCheckedChange: entry.onCheckedChange }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={[styles.item, styles.checkbox]}
                  tabindex="-1"
                  ><span class={styles.check}
                    >{#if entry.checked}<Icon name="confirm" size="sm" />{/if
                  }</span
                  ><span class={styles.label}>{entry.label}</span
                ></div
              >{:else if entry.kind === 'submenu'
                }<MenubarSubmenu {entry}
              />{:else
                }<div
                  {...attributes(mergeParts(api.getItemProps({ value: entry.label, disabled: entry.disabled }), { onFocus: () => { api.setHighlightedValue(entry.label) } }))}
                  class={styles.item}
                  data-tone={entry.tone ?? 'neutral'}
                  tabindex="-1"
                  >{#if entry.icon !== undefined
                    }<span class={styles.glyph}><Icon name={entry.icon} size="sm" /></span
                  >{/if
                  }<span class={styles.label}>{entry.label}</span
                  >{#if entry.kbd !== undefined
                    }<span class={styles.hint}><Kbd>{entry.kbd}</Kbd></span
                  >{/if
                }</div
              >{/if
            }{/each
          }</div
        ></div
      >{/if
    }</Portal
  >{/if
}{/if
}{@render joined.end?.()}
